CREATE TABLE user_roles (user_role_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_role_name VARCHAR(50));
CREATE TABLE "user" (user_id VARCHAR(100) PRIMARY KEY, user_name VARCHAR(100), user_password VARCHAR(100), user_role_id INT REFERENCES user_roles(user_role_id), user_inst_id INT);
CREATE TABLE system_objects (sys_object_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sys_object_name VARCHAR(100), sys_object_display_name VARCHAR(100));
CREATE TABLE object_user_role_perm (perm_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, perm_sys_object_id INT, perm_user_role_id INT, create_perm CHAR(1) DEFAULT 'N', read_perm CHAR(1) DEFAULT 'N', update_perm CHAR(1) DEFAULT 'N', delete_perm CHAR(1) DEFAULT 'N', execute_perm CHAR(1) DEFAULT 'N');
